        self._emit_trace(f"Loading method: {FilePath}")
        instance.send_intermediate_response(
            LoadMethod_IntermediateResponses(StatusUpdate="Loading method...")
        )

        try:
            result = self._client.load_method(FilePath, simulation=Simulation)
        except Exception as e:
            raise VenusConnectionError(f"Failed to load method: {e}") from e

        # VENUS loads asynchronously — poll run-state until Initialized (1)
        # RunState enum: 0=Unknown, 1=Initialized, 2=Running, 3=Paused,
        #   4=Finished, 5=Aborted, 6=Error, 7=WaitingForInput, 8=Starting, 9=Finishing
